mapper.select:
select

from og_reserarch


        and research_direction = #{direction}


        and reserarch_author like concat('%', #{author}, '%')


        and reserarch_title like concat('%', #{title}, '%')


        and (reserarch_title like concat('%', #{keyword}, '%')
            or reserarch_author like concat('%', #{keyword}, '%'))


        and coalesce(publication_year, year(create_time)) = #{year}


        and publication_type = #{type}


        and reserarch_source like concat('%', #{resource}, '%')


        and venue_short_name = #{venue}


order by coalesce(publication_year, year(create_time)) desc, is_new desc, create_time desc
